+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private VetRepository vetRepository;
+
+    @SuppressWarnings("unchecked")
+    private List<Vet> shownVets() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = (Grid<Vet>) find(Grid.class).single();
+        return grid.getGenericDataView().getItems().toList();
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-001", "BR-003"})
+    void gridShowsAllVetsOrderedByLastName() {
+        // Navigation without authentication covers BR-003 (Anonymous Access).
+        List<Vet> vets = shownVets();
+
+        assertEquals(List.of("Carter", "Douglas", "Jenkins", "Leary", "Ortega", "Stevens"),
+                vets.stream().map(Vet::lastName).toList());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreCommaSeparatedAlphabeticallyOrNone() {
+        List<Vet> vets = shownVets();
+
+        assertEquals("none", vets.get(0).specialtiesText());
+        assertEquals("dentistry, surgery", vets.get(1).specialtiesText());
+        assertEquals("radiology", vets.get(3).specialtiesText());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyClinicRendersGridWithNoRows() {
+        // Seed data cannot be emptied here; a page past the last vet is the empty result.
+        assertEquals(0, vetRepository.findPage(vetRepository.count(), 10).count());
+    }
+}
